// BEFORE: Long method with multiple responsibilities
function processOrder(order: Order): OrderResult {
  // Validate order
  if (!order.customerId) return null;
  if (!order.items || order.items.length === 0) return null;

  // Calculate totals
  let subtotal = 0;
  let tax = 0;
  let shipping = 0;

  for (const item of order.items) {
    subtotal += item.price * item.quantity;
    if (item.category === 'food') {
      tax += item.price * item.quantity * 0.08;
    }
    if (item.weight > 10) {
      shipping += item.weight * 0.5;
    }
  }

  const total = subtotal + tax + shipping;  
  // Apply discount
  let discount = 0;
  if (order.customerType === 'premium' && total > 100) {
    discount = total * 0.1;
  }

  const finalTotal = total - discount;  
  // Create order result
  return {
    orderId: order.id,
    subtotal,
    tax,
    shipping,
    discount,
    total: finalTotal,
    timestamp: new Date().toISOString()
  };
}

// AFTER: Refactored with extracted methods
interface OrderTotals {
  subtotal: number;
  tax: number;
  shipping: number;
}

function calculateOrderTotals(items: OrderItem[]): OrderTotals {
  let subtotal = 0;
  let tax = 0;
  let shipping = 0;

  for (const item of items) {
    subtotal += item.price * item.quantity;
    tax += calculateTax(item);
    shipping += calculateShipping(item);
  }

  return { subtotal, tax, shipping };
}

function calculateDiscount(customerType: string, subtotal: number): number {
  return customerType === 'premium' && subtotal > 100 ? subtotal * 0.1 : 0;
}

function processOrder(order: Order): OrderResult | null {
  if (!isValidOrder(order)) return null;

  const totals = calculateOrderTotals(order.items);
  const discount = calculateDiscount(order.customerType, totals.subtotal);

  return {
    orderId: order.id,
    ...totals,
    discount,
    finalTotal: totals.subtotal + totals.tax + totals.shipping - discount,
    timestamp: new Date().toISOString()
  };
}


// BEFORE: Complex conditional logic
function calculateShipping(items: OrderItem[], customerType: string): number {
  if (customerType === 'premium') {
    return items.reduce((total, item) => {
      if (item.weight > 10) {
        return total + item.weight * 0.2; // Premium: expedited shipping
      } else {
        return total + items.reduce((sum, i) => sum + i.weight, 0) * 0.5; // Premium: standard shipping
      }
    }, 0);
  } else {
    return items.reduce((total, item) => {
      if (item.weight > 5) {
        return total + item.weight * 0.8; // Standard: overweight items
      } else {
        return total + items.reduce((sum, i) => sum + i.weight, 0) * 0.5; // Standard: regular shipping
      }
    }, 0);
  }
}

// AFTER: Polymorphic strategy pattern
interface ShippingStrategy {
  calculate(items: OrderItem[]): number;
}

class PremiumShippingStrategy implements ShippingStrategy {
  calculate(items: OrderItem[]): number {
    return items.reduce((total, item) => {
      if (item.weight > 10) {
        return total + item.weight * 0.2; // Expedited
      } else {
        return total + item.weight * 0.5; // Standard
      }
    }, 0);
  }
}

class StandardShippingStrategy implements ShippingStrategy {
  calculate(items: OrderItem[]): number {
    return items.reduce((total, item) => {
      if (item.weight > 5) {
        return total + item.weight * 0.8; // Overweight
      } else {
        return total + items.reduce((sum, i) => sum + i.weight, 0) * 0.5; // Regular
      }
    }, 0);
  }
}

function calculateShipping(items: OrderItem[], customerType: string, strategy: ShippingStrategy): number {
  return strategy.calculate(items);
}

// Usage
const premiumStrategy = new PremiumShippingStrategy();
const standardStrategy = new StandardShippingStrategy();

const shippingCost = calculateShipping(order.items, order.customerType, 
  order.customerType === 'premium' ? premiumStrategy : standardStrategy
);


// Characterization tests first
describe('UserService', () => {
  it('should create user with valid data', async () => {
    const userService = new UserService();
    const user = await userService.createUser({
      email: 'test@example.com',
      name: 'Test User',
      age: 25
    });

    expect(user.email).toBe('test@example.com');
    expect(user.name).toBe('Test User');
    expect(user.age).toBe(25);
    expect(user.isActive).toBe(true);
  });

  it('should validate user data', async () => {
    const userService = new UserService();

    await expect(userService.createUser({
      email: '', // Invalid email
      name: 'Test User',
      age: 25
    })).rejects.toThrow('Email and name required');
  });
});

// STEP 1: Extract validation logic
class UserValidator {
  static validateEmail(email: string): boolean {
    return email.includes('@');
  }

  static validateName(name: string): boolean {
    return name.length > 0;
  }

  static validateAge(age: number): boolean {
    return age >= 18 && age <= 120;
  }
}

