class UserService {
  private users: User[] = [];
  private database: UserDatabase;
  private validator: typeof UserValidator;

  constructor(database: UserDatabase) {
    this.database = database;
    this.validator = UserValidator;
  }

  async loadUsers(): Promise<void> {
    this.users = await this.database.fetchUsers();
  }

  async createUser(userData: CreateUserRequest): Promise<User> {
    this.validator.validateEmail(userData.email);
    this.validator.validateName(userData.name);
    this.validator.validateAge(userData.age);

    const user = this.createUserObject(userData);
    await this.database.saveUser(user);
    return user;
  }

  // ... other methods using validator and database
}


// BEFORE: Legacy callback-based code
class LegacyDataService {
  getUser(id: string, callback: (user: User | null) => void): void {
    setTimeout(() => {
      const user = this.findUserById(id);
      callback(user);
    }, 100);
  }

  private findUserById(id: string): User | null {
    // Database lookup logic
    return { id, name: 'User ' + id };
  }
}

// AFTER: Modernized with Promises
class ModernDataService {
  async getUser(id: string): Promise<User | null> {
    const user = await this.findUserById(id);
    return user;
  }

  private async findUserById(id: string): Promise<User | null> {
    // Database lookup logic
    return { id, name: 'User ' + id };
  }
}

// Usage comparison
// Legacy usage
const legacyService = new LegacyDataService();
legacyService.getUser('123', (user) => {
  if (user) {
    console.log('Found user:', user.name);
  }
});

// Modern usage
const modernService = new ModernDataService();
modernService.getUser('123').then(user => {
  if (user) {
    console.log('Found user:', user.name);
  }
});
